<?php
require_once __DIR__ . '/bootstrap.php';
$role = $user['role_name'];
$tabs = ['loans' => t('Loan portfolio')];
if (in_array($role, ['SUPER_ADMIN', 'MANAGER', 'FIRM'], true)) { $tabs = ['applications' => t('Applications')] + $tabs; }
if (in_array($role, ['SUPER_ADMIN', 'ACCOUNTANT'], true)) { $tabs['payments'] = t('Payment confirmations'); }
if (in_array($role, ['SUPER_ADMIN', 'MANAGER', 'RECOVERY_OFFICER'], true)) { $tabs['overdue'] = t('Overdue loans'); }
$tab = $_GET['tab'] ?? ($role === 'RECOVERY_OFFICER' ? 'overdue' : array_key_first($tabs));
if (!is_string($tab) || !isset($tabs[$tab])) { $tab = array_key_first($tabs); }
$page = max(1, (int) ($_GET['page'] ?? 1));
$status = is_string($_GET['status'] ?? null) ? $_GET['status'] : '';
$validStatuses = $tab === 'applications' ? ['SUBMITTED','UNDER_REVIEW','APPROVED','REJECTED','CANCELLED'] : ['APPROVED','ACTIVE','DISBURSED','COMPLETED','OVERDUE','DEFAULTED','WRITTEN_OFF'];
if (!in_array($status, $validStatuses, true)) { $status = ''; }
$summary = $lending->summary();
$items = match ($tab) {
    'applications' => $lending->applications($status, $page),
    'payments' => $lending->pendingPayments($page),
    'overdue' => $lending->loans('OVERDUE', $page),
    default => $lending->loans($status, $page),
};
$hasNext = count($items) > 20;
$items = array_slice($items, 0, 20);
$title = t('Lending workspace');
require __DIR__ . '/../includes/header.php';
?>
<div class="page-heading"><div><span class="eyebrow"><?= e(role_label($role)) ?> <?= e(t('workspace')) ?></span><h1><?= $role === 'RECOVERY_OFFICER' ? t('Keep every loan on track.') : t('A clearer view of lending.') ?></h1><p><?= e($user['firm_name'] ?? t('All lending firms')) ?> <?= e(t('· Review progress and take the next step.')) ?></p></div><?php if (in_array($role, ['SUPER_ADMIN', 'MANAGER', 'ACCOUNTANT'], true)): ?><a class="button secondary" href="<?= e(app_url('workspace/reports.php')) ?>"><?= e(t('View reports ↗')) ?></a><?php endif; ?></div>
<div class="metrics metrics-four"><div class="card metric"><span class="label"><?= e(t('Outstanding portfolio')) ?></span><div class="number compact-number"><?= e(format_number((float) $summary['outstanding'])) ?><small> RWF</small></div><span class="metric-foot"><?= e(t('Disbursed loans')) ?></span></div><div class="card metric"><span class="label"><?= e(t('Confirmed repayments')) ?></span><div class="number compact-number"><?= e(format_number((float) $summary['repaid'])) ?><small> RWF</small></div><span class="metric-foot"><?= e(t('All time collections')) ?></span></div><div class="card metric"><span class="label"><?= e(t('Awaiting disbursement')) ?></span><div class="number"><?= e($summary['awaiting_disbursement']) ?></div><span class="metric-foot"><?= e(t('Approved loans')) ?></span></div><div class="card metric"><span class="label"><?= e(t('Overdue loans')) ?></span><div class="number"><?= e($summary['overdue']) ?></div><span class="metric-foot"><?= e(t('With unpaid past-due installments')) ?></span></div></div>
<nav class="tabs" aria-label="<?= e(t('Lending workspace')) ?>"><?php foreach ($tabs as $key => $label): ?><a class="<?= $tab === $key ? 'active' : '' ?>" href="<?= e(app_url('workspace/index.php?tab=' . $key)) ?>"><?= e(t($label)) ?></a><?php endforeach; ?></nav>
<section class="card"><div class="section-heading"><h2><?= e($tabs[$tab]) ?></h2><?php if (in_array($tab, ['applications','loans'], true)): ?><form class="filter-form" method="GET"><input type="hidden" name="tab" value="<?= e($tab) ?>"><label class="sr-only" for="status"><?= e(t('Filter by status')) ?></label><select id="status" name="status"><option value=""><?= e(t('All statuses')) ?></option><?php foreach ($validStatuses as $value): ?><option value="<?= e($value) ?>" <?= $status === $value ? 'selected' : '' ?>><?= e(status_label($value)) ?></option><?php endforeach; ?></select><button class="button secondary small"><?= e(t('Filter')) ?></button></form><?php endif; ?></div>
<?php if (!$items): ?><div class="empty"><span class="empty-symbol">✓</span><h3><?= e(t('Nothing here yet.')) ?></h3><p><?= e(t('Records matching this view will appear here.')) ?></p></div><?php elseif ($tab === 'payments'): ?>
<div class="firm-list"><?php foreach ($items as $row): ?><article class="payment-review-card"><div><span class="eyebrow"><?= e(t('Loan #')) ?><?= e($row['loan_id']) ?></span><h3><?= e($row['full_name']) ?></h3><div class="balance-value small-balance"><?= e(money($row['amount_rwf'])) ?></div><p class="muted"><?= e(format_date($row['payment_date'])) ?> · <?= e(enum_label($row['payment_method'])) ?></p><strong><?= e($row['reference_code']) ?></strong><p><a href="<?= e(app_url('workspace/loan.php?id=' . $row['loan_id'])) ?>"><?= e(t('Open loan →')) ?></a></p></div><form class="review" method="POST" action="<?= e(app_url('workspace/action.php')) ?>"><?= csrf_field() ?><input type="hidden" name="action" value="payment_review"><input type="hidden" name="id" value="<?= e($row['submission_id']) ?>"><p class="help"><?= e(t('Verify the transfer in your bank or mobile money records before confirming.')) ?></p><div class="field"><label for="payment-note-<?= e($row['submission_id']) ?>"><?= e(t('Review note (required to reject)')) ?></label><textarea id="payment-note-<?= e($row['submission_id']) ?>" name="notes" maxlength="1000"></textarea></div><div class="review-actions"><button class="button small" name="decision" value="CONFIRMED"><?= e(t('Confirm payment')) ?></button><button class="button danger small" name="decision" value="REJECTED"><?= e(t('Reject')) ?></button></div></form></article><?php endforeach; ?></div>
<?php else: ?><div class="table-wrap"><table class="data-table"><thead><tr><th><?= e(t('Customer')) ?></th><th><?= e(t('Product')) ?></th><th><?= $tab === 'applications' ? t('Requested amount') : t('Outstanding balance') ?></th><th><?= e(t('Status')) ?></th><th></th></tr></thead><tbody><?php foreach ($items as $row): ?><tr><td><strong><?= e($row['full_name']) ?></strong><span class="cell-note">#<?= e($tab === 'applications' ? $row['application_id'] : $row['loan_id']) ?></span></td><td><?= e($row['product_name']) ?><span class="cell-note"><?= e($row['term_months']) ?> <?= e(t('months')) ?></span></td><td class="amount"><?= e(money($tab === 'applications' ? $row['amount_requested_rwf'] : $row['outstanding_balance_rwf'])) ?></td><td><?= status_badge($row['display_status'] ?? $row['status']) ?></td><td><a href="<?= e(app_url('workspace/' . ($tab === 'applications' ? 'application.php?id=' . $row['application_id'] : 'loan.php?id=' . $row['loan_id']))) ?>"><?= e(t('Open →')) ?></a></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?>
</section>
<nav class="pagination" aria-label="<?= e(t('Workspace pages')) ?>"><?php if ($page > 1): ?><a class="button secondary small" href="<?= e(app_url('workspace/index.php?' . http_build_query(['tab'=>$tab,'status'=>$status,'page'=>$page-1]))) ?>"><?= e(t('Previous')) ?></a><?php endif; ?><span class="muted"><?= e(t('Page')) ?> <?= e($page) ?></span><?php if ($hasNext): ?><a class="button secondary small" href="<?= e(app_url('workspace/index.php?' . http_build_query(['tab'=>$tab,'status'=>$status,'page'=>$page+1]))) ?>"><?= e(t('Next')) ?></a><?php endif; ?></nav>
<?php require __DIR__ . '/../includes/footer.php'; ?>
